        }
    }

    // 状态转移
    for (int i = 0; i < (1 << n); ++i) {
        for (int j = 0; j < n; ++j) {
            if (i >> j & 1) continue;
            for (int rem = 0; rem < k; ++rem) {
                if (dp[i][rem] == 0) continue;
                int nxt = (rem * 10 + (x[j] - '0')) % k;
                dp[i | (1 << j)][nxt] += dp[i][rem];
            }
        }
    }

    ll ans = dp[(1 << n) - 1][0];

    // 去重：除以相同数字出现次数的阶乘
